import { bulk_reject_workflows } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    bulkRejectDialog: Boolean,
    allselecctedRecords: Array
  },
  data() {
    return {
      approvalComments: "",
      loading: false
    };
  },
  watch: {
    bulkRejectDialog: {
      async handler() {
        if (this.bulkRejectDialog == true) {}
      },
      immediate: true
    }
  },
  methods: {
    async validate_aprrovals() {
      const {
        valid
      } = await this.$refs.form1.validate();
      if (valid) {
        this.bulk_reject_ids();
      }
    },
    async bulk_reject_ids() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(bulk_reject_workflows, {
          input: {
            user_email_id: data.user.user_email_id,
            initiate_id: this.allselecctedRecords,
            comments: this.approvalComments
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.bulk_reject_workflows);
        if (response.Status == "SUCCESS") {
          this.loading = false;
          this.$emit("successMsg", response.Message);
          this.$refs.form1.reset();
        } else {
          this.loading = false;

          // this.formCheck = false;
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        // console.log(error);
        this.loading = false;
      }
    },
    fetch_all_ids() {
      var array = [];
      this.allselecctedRecords.forEach(element => {
        array.push(element.initiate_id);
      });
      return array;
    },
    close_dialog() {
      this.$emit("clicked", 0);
      this.$refs.form1.reset();
    }
  }
};
